package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/retailers/me/products") public class CatalogueController {private final CatalogueService service;public CatalogueController(CatalogueService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<ProductResponse>> create(@Valid @RequestBody ProductRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Product created",service.create(r)));}@GetMapping("/{id}") public ApiResponse<ProductResponse> get(@PathVariable Long id,HttpServletRequest h){return ok(h,"Product retrieved",service.get(id));}@GetMapping public ApiResponse<PageResponse<ProductResponse>> search(@RequestParam(required=false) String q,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) String status,@RequestParam(required=false) String inventoryStatus,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Catalogue retrieved",service.search(q,categoryId,status,inventoryStatus,page,size));}@GetMapping("/summary") public ApiResponse<CatalogueSummaryResponse> summary(HttpServletRequest h){return ok(h,"Catalogue summary retrieved",service.summary());}@PatchMapping("/{id}") public ApiResponse<ProductResponse> update(@PathVariable Long id,@Valid @RequestBody ProductRequest r,HttpServletRequest h){return ok(h,"Product updated",service.update(id,r));}@PostMapping("/{id}/duplicate") public ResponseEntity<ApiResponse<ProductResponse>> duplicate(@PathVariable Long id,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Product duplicated",service.duplicate(id)));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}